    Bug 1923526 - Close and clean up temporary output stream on compact failure. r=BenC,kaie

    Differential Revision: https://phabricator.services.mozilla.com/D227571

diff --git a/mailnews/base/test/unit/test_folderCompact.js b/mailnews/base/test/unit/test_folderCompact.js
index 1c366c6f09e..c05df55867d 100644
--- a/mailnews/base/test/unit/test_folderCompact.js
+++ b/mailnews/base/test/unit/test_folderCompact.js
@@ -246,6 +246,10 @@ add_task(async function testAbortCompactingFolder() {

   showMessages(gFolder2, "before deleting 1 message");

+  const filesBefore = new Set(
+    Array.from(gFolder2.filePath.parent.directoryEntries, f => f.leafName)
+  );
+
   // Remember the size of the mbox before compact.
   const unchangedFolderSize = calculateExpectedMboxSize(gFolder2);

@@ -271,6 +275,20 @@ add_task(async function testAbortCompactingFolder() {
   await verifyMboxSize(gFolder2, unchangedFolderSize);
   Assert.greater(gFolder2.expungedBytes, 0, "folder2 should need compaction");

+  const filesAfter = new Set(
+    Array.from(gFolder2.filePath.parent.directoryEntries, f => f.leafName)
+  );
+  Assert.deepEqual(
+    [...filesBefore.difference(filesAfter)],
+    [],
+    "there should be no files removed after compaction aborted"
+  );
+  Assert.deepEqual(
+    [...filesAfter.difference(filesBefore)],
+    [],
+    "there should be no new files after compaction aborted"
+  );
+
   Assert.equal(
     Glean.mail.compactResult[Cr.NS_OK.toString(16)].testGetValue(),
     null,
diff --git a/mailnews/local/src/nsMsgBrkMBoxStore.cpp b/mailnews/local/src/nsMsgBrkMBoxStore.cpp
index 3ca98ddfb96..df1042c40e3 100644
--- a/mailnews/local/src/nsMsgBrkMBoxStore.cpp
+++ b/mailnews/local/src/nsMsgBrkMBoxStore.cpp
@@ -485,7 +485,12 @@ NS_IMETHODIMP MboxCompactor::OnStopScan(nsresult status) {
     nsCOMPtr<nsISafeOutputStream> safe = do_QueryInterface(mDestStream, &rv);
     if (NS_SUCCEEDED(rv)) {
       rv = safe->Finish();
+    } else {
+      // How did we get here? This should never happen.
+      rv = mDestStream->Close();
     }
+  } else if (mDestStream) {
+    mDestStream->Close();  // Clean up temporary file.
   }

   int64_t finalSize = 0;
@@ -1416,7 +1421,7 @@ nsMsgBrkMBoxStore::GetMsgInputStream(nsIMsgFolder* aMsgFolder,
   NS_ENSURE_SUCCESS(rv, rv);
   // Stream to return a single message, hiding all "From "-separator guff.
   RefPtr<MboxMsgInputStream> msgStream =
-    new MboxMsgInputStream(rawMboxStream, aMaxAllowedSize);
+      new MboxMsgInputStream(rawMboxStream, aMaxAllowedSize);
   msgStream.forget(aResult);
   return NS_OK;
 }
